import time


class Csv_Handle(object):
    def __init__(self):
        pass

    def parse_key_value(self, line):
        'key value'
        pass

    def msg_2_dict(self, data):
        'dict'
        pass

    def parse_single_msg(self, msg):
        'null'
        useful_list = []
        lines = msg.splitlines()
        for line in lines:
            if '=' in line:
                useful_list.append(line.replace('=', ' = '))
        return useful_list

    def parse_file(self, log_file_path):
        'null'
        with open(log_file_path, 'r') as obj:
            lines = obj.read()
        msg_dict = {}

        line_num = []
        lines = lines.splitlines()
        start = 0
        raw_datas = []
        raw_dict = {}
        title_items_len = 0
        st = time.time()
        for line in range(len(lines)):
            line = lines[line]
            item_list = line.strip(',').split(',')
            if 'Time' in line:
                title_items_len = len(item_list)
                for i in range(len(item_list)):
                    msg_dict[i] = [item_list[i]]
            elif title_items_len == len(item_list) and 'Time' not in line:
                for i in range(len(item_list)):
                    msg_dict[i] += [item_list[i]]
        return msg_dict
